in linen.","alternatives":[{"id":"01a21904-ad5f-757e-a2b5-6f49d96ef8df","description":"A mummy","correct_answer":true},{"id":"01a21904-ad5f-7041-b4ba-c0f8b2848fb1","description":"A zombie","correct_answer":false},{"id":"01a21904-ad5f-7140-9cc9-0d227ae67fb0","description":"A skeleton","correct_answer":false},{"id":"01a21904-ad5f-709d-b122-4db5578ce4aa","description":"A vampire","correct_answer":false}]},{"id":"01a21904-ad5f-7b07-9f76-18276d3fed96","category":"01a21312-b489-7dd6-93ca-116c8464996a","question":"What did \'my true love give to me\' on the first day of Christmas?","difficulty":1,"explanation":"A Partridge in a Pear Tree is the gift in the carol\u2019s opening verse. Each succeeding verse adds gifts while repeating those already named.","alternatives":[{"id":"01a21904-ad5f-7ee4-8314-f843d4fce216","description":"A Partridge In A Pear Tree","correct_answer":true},{"id":"01a21904-ad5f-7ca6-91e7-22c1c2a27c5f","description":"5 Gold Rings","correct_answer":false},{"id":"01a21904-ad5f-73e5-83ae-04724807ccb5","description":"A Turtle Dove","correct_answer":false},{"id":"01a21904-ad5f-77a9-b6a3-151cac986cba","description":"True Love","correct_answer":false}]},{"id":"01a21904-ad5f-71a9-bcdb-5c282dfe9f14","category":"01a21312-b489-7dd6-93ca-116c8464996a","question":"After rejoining Apple in 1997, Steve Jobs engineered what ad campaign?","difficulty":1,"explanation":"Think Different used portraits of figures such as Albert Einstein and Martin Luther King Jr. to link Apple with creativity and nonconformity.","alternatives":[{"id":"01a21904-ad5f-773f-b469-5d9053b8f6a1","description":"Think Different","correct_answer":true},{"id":"01a21904-ad5f-79b9-8ecb-29470444cc04","description":"Just Do It","correct_answer":false},{"id":"01a21904-ad5f-780b-8516-01ddcc477941","description":"I\'m Lovin\' It","correct_answer":false},{"id":"01a21904-ad5f-7c4d-ad0f-0e5c0bee7450","description":"Got Milk?","correct_answer":false}]},{"id":"01a21904-ad5f-7aa6-af7f-ab8c21d37501","category":"01a